<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\Request;
use Sentinel\Tests\FieldFixture;
final class WorkspaceUiTest extends TestCase
{
 public function testSiteChoicesFollowAdministratorClientGuardAndRestrictedScopes():void {
  [$app,$db,$ctx]=FieldFixture::create();$access=$app->container()->make('site_access_service');$auth=$app->container()->make('authorization_service');self::assertSame([1,2],array_column($access->workspaceSites($auth)['sites'],'site_id'));foreach($access->workspaceSites($auth)['sites']as$site)self::assertSame(['site_id','site_name'],array_keys($site));
  $ctx->setUser('2');self::assertSame([],$access->workspaceSites($auth)['sites']);$db->execute("INSERT INTO role_permissions(company_id,role_id,permission_id) SELECT 101,2,permission_id FROM permissions WHERE company_id=101 AND permission_code='risk_assessments.client'");$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');self::assertSame([1],array_column($access->workspaceSites($auth)['sites'],'site_id'));$db->execute('DELETE FROM client_portal_access');$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,assignment_status,shift_end_at) VALUES(1,101,2,1,'ASSIGNED',:end)",['end'=>gmdate('Y-m-d H:i:s',time()+3600)]);self::assertSame([1],array_column($access->workspaceSites($auth)['sites'],'site_id'));$db->execute("UPDATE shift_assignments SET assignment_status='CANCELLED'");self::assertSame([],$access->workspaceSites($auth)['sites']);
  $ctx->setUser('1');$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$db->execute('INSERT INTO role_permissions VALUES(1,9001,101)');self::assertSame([],$access->workspaceSites($auth)['sites']);$db->execute('INSERT INTO user_site_grants(company_id,user_id,site_id,granted_by_user_id,granted_at) VALUES(101,1,1,1,:now)',['now'=>gmdate('Y-m-d H:i:s')]);self::assertSame([1],array_column($access->workspaceSites($auth)['sites'],'site_id'));$ctx->setTenantId(202);$ctx->setUser('3');self::assertSame([3],array_column($access->workspaceSites($auth)['sites'],'site_id'));
 }
 public function testAuthenticatedDiscoveryIncludesVerifiedIdentityAndNoOtherTenantSites():void {[$app,$db,$ctx]=FieldFixture::create();$token=$app->jwt()->createToken('1',true);$headers=['Authorization'=>'Bearer '.$token];$r=$app->handle(Request::create('GET','/api/v1/auth/access',[],$headers));$data=json_decode($r->body(),true)['data'];self::assertSame('1',$data['user_id']);self::assertSame('101',$data['company_id']);$r=$app->handle(Request::create('GET','/api/v1/auth/workspace-sites',['company_id'=>202],$headers));self::assertSame(200,$r->status());self::assertSame([1,2],array_column(json_decode($r->body(),true)['data']['sites'],'site_id'));self::assertSame('no-store',$r->header('Cache-Control'));}
 public function testAdvertisedTwoMiBPhotoFitsTheDefaultApiRequestLimit():void {[$app,$db,$ctx]=FieldFixture::create();$png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6zAAAAABJRU5ErkJggg==');$bytes=$png.str_repeat('x',2097000-strlen($png));$body=json_encode(['site_id'=>1,'description'=>'Bounded photo','found_location'=>'Gate','storage_location'=>'Locker','found_at'=>gmdate('Y-m-d H:i:s'),'photo_base64'=>base64_encode($bytes)],JSON_THROW_ON_ERROR);self::assertGreaterThan(1048576,strlen($body));$token=$app->jwt()->createToken('1',true);$r=$app->handle(Request::create('POST','/api/v1/found-property',[],['Authorization'=>'Bearer '.$token,'Content-Type'=>'application/json'],$body));self::assertSame(200,$r->status(),$r->body());self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM found_property')['n']);}
 public function testRestrictedSiteChoicesApplyScopeBeforeTheDirectoryLimit():void {[$app,$db,$ctx]=FieldFixture::create();for($i=10;$i<515;$i++)$db->execute('INSERT INTO sites(site_id,company_id,client_id,site_name) VALUES(:id,101,1,:name)',['id'=>$i,'name'=>'Directory fixture '.str_pad((string)$i,4,'0',STR_PAD_LEFT)]);$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$db->execute('INSERT INTO role_permissions VALUES(1,9001,101)');$db->execute('INSERT INTO user_site_grants(company_id,user_id,site_id,granted_by_user_id,granted_at) VALUES(101,1,2,1,:now)',['now'=>gmdate('Y-m-d H:i:s')]);$result=$app->container()->make('site_access_service')->workspaceSites($app->container()->make('authorization_service'));self::assertSame([2],array_column($result['sites'],'site_id'));self::assertFalse($result['truncated']);}
}
